<?php $flash=$_SESSION['user_flash']??null;unset($_SESSION['user_flash']); ?>
<section class="space-y-6"><header><p class="text-sm font-semibold uppercase tracking-widest text-primary">Access management</p><h1 class="mt-2 text-3xl font-bold">Roles &amp; Permissions</h1><p class="mt-2 text-zinc-600 dark:text-zinc-300">Choose what Admin and Staff roles can access. Admin retains full access.</p></header>
    <?php if(is_array($flash)): ?><p role="status" class="rounded-lg border px-4 py-3 text-sm <?= ($flash['type']??'')==='success'?'border-green-200 bg-green-50 text-green-800 dark:border-green-900 dark:bg-green-950 dark:text-green-200':'border-red-200 bg-red-50 text-red-800 dark:border-red-900 dark:bg-red-950 dark:text-red-200' ?>"><?= e($flash['message']??'') ?></p><?php endif; ?>
    <nav class="flex gap-2 rounded-xl bg-white p-2 shadow-sm ring-1 ring-zinc-200 dark:bg-dark-card dark:ring-zinc-800"><a href="/users" class="rounded-lg px-4 py-2 text-sm font-medium text-zinc-600 hover:bg-zinc-100 dark:text-zinc-300 dark:hover:bg-zinc-800">Users</a><a aria-current="page" href="/roles" class="rounded-lg bg-violet-50 px-4 py-2 text-sm font-semibold text-primary dark:bg-violet-950/50">Roles &amp; Permissions</a></nav>
    <div class="grid gap-5 xl:grid-cols-2"><?php foreach($roles as $role): ?><form method="post" action="/roles/<?= (int)$role['id'] ?>/permissions" class="rounded-xl bg-white p-5 shadow-sm ring-1 ring-zinc-200 dark:bg-dark-card dark:ring-zinc-800"><input type="hidden" name="_csrf_token" value="<?= e($csrfToken) ?>"><div class="mb-4 flex items-start justify-between gap-3"><div><h2 class="text-xl font-semibold capitalize"><?= e($role['name']) ?></h2><p class="mt-1 text-sm text-zinc-500 dark:text-zinc-400"><?= e($role['description']??'') ?></p></div><span class="rounded-full bg-violet-50 px-2.5 py-1 text-xs font-semibold text-primary dark:bg-violet-950/50 dark:text-violet-300"><?= $role['name']==='admin'?'Full access':'Role permissions' ?></span></div>
        <?php $grouped=[];foreach($permissions as $permission)$grouped[$permission['module']][]=$permission; ?>
        <div class="space-y-4"><?php foreach($grouped as $module=>$modulePermissions): ?><fieldset><legend class="mb-2 text-sm font-semibold"><?= e($module) ?></legend><div class="grid gap-2 sm:grid-cols-2"><?php foreach($modulePermissions as $permission): $checked=in_array((int)$permission['id'],$role['permission_ids'],true); $locked=$role['name']==='admin'||($role['name']!=='admin'&&$permission['permission_key']==='roles.manage'); ?><label class="flex items-center gap-2 rounded-lg border border-zinc-100 px-3 py-2 text-sm dark:border-zinc-800"><input type="checkbox" name="permissions[]" value="<?= (int)$permission['id'] ?>" <?= $checked?'checked':'' ?> <?= $locked?'disabled':'' ?> class="size-4 rounded border-zinc-300 text-primary focus:ring-primary"><span><?= e($permission['label']) ?><?= $permission['permission_key']==='roles.manage'?' <small class="text-zinc-400">(Admin only)</small>':'' ?></span></label><?php endforeach; ?></div></fieldset><?php endforeach; ?></div>
        <?php if($role['name']!=='admin'): ?><div class="mt-5 flex justify-end"><button class="rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-white hover:bg-primary-hover" type="submit">Save staff permissions</button></div><?php else: ?><p class="mt-4 text-xs text-zinc-500">Administrator access is fixed to prevent accidental lockout.</p><?php endif; ?></form><?php endforeach; ?></div>
</section>
